"use client";

import {
  CircleCheckIcon,
  InfoIcon,
  Loader2Icon,
  OctagonXIcon,
  TriangleAlertIcon,
} from "lucide-react";
import { useTheme } from "next-themes";
import { Toaster as Sonner } from 'sonner';
import type { ToasterProps } from 'sonner';

const Toaster = ({ ...props }: ToasterProps) => {
  const { theme = "system" } = useTheme();

  return (
    <Sonner
      theme={theme as ToasterProps["theme"]}
      className="toaster group"
      icons={{
        error: <OctagonXIcon className="size-4" />,
        info: <InfoIcon className="size-4" />,
        loading: <Loader2Icon className="size-4 animate-spin" />,
        success: <CircleCheckIcon className="size-4" />,
        warning: <TriangleAlertIcon className="size-4" />,
      }}
      style={
        {
          "--border-radius": "var(--radius)",
          "--normal-bg": "var(--popover)",
          "--normal-border": "var(--border)",
          "--normal-text": "var(--popover-foreground)",
        } as React.CSSProperties
      }
      {...props}
    />
  );
};

export { Toaster };
export default Toaster;

"use client";

import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Toaster } from "@/components/ui/sonner";

export function SonnerDemo() {
  return (
    <div className="flex flex-col gap-4">
      <Toaster />
      <div className="flex flex-wrap gap-2">
        <Button variant="outline" onClick={() => toast("File saved successfully.")}>
          Default
        </Button>
        <Button variant="outline" onClick={() => toast.success("Changes saved.")}>
          Success
        </Button>
        <Button variant="outline" onClick={() => toast.error("Something went wrong.")}>
          Error
        </Button>
        <Button variant="outline" onClick={() => toast.warning("Disk space is low.")}>
          Warning
        </Button>
        <Button variant="outline" onClick={() => toast.info("A new version is available.")}>
          Info
        </Button>
        <Button
          variant="outline"
          onClick={() =>
            toast.loading("Uploading…", {
              duration: 3000,
            })
          }
        >
          Loading
        </Button>
        <Button
          variant="outline"
          onClick={() =>
            toast("File deleted.", {
              action: { label: "Undo", onClick: () => toast.success("Restored.") },
              description: "report.pdf was moved to trash.",
            })
          }
        >
          With action
        </Button>
        <Button
          variant="outline"
          onClick={() =>
            toast("Profile updated.", {
              description: "Your changes have been saved to the server.",
            })
          }
        >
          With description
        </Button>
      </div>
    </div>
  );
}


export default function Page() {
  return (
    <div className="flex min-h-svh items-center justify-center p-8 bg-background">
      <SonnerDemo />
    </div>
  );
}
